)

for FILE in "${REQUIRED_FILES[@]}"
do
  test -f "$FILE" || {
    printf 'ERROR: Thiếu source bắt buộc: %s\n' "$FILE" >&2
    exit 1
  }
done

grep -Fq "luxe_clarity_v1" \
  app/Services/CommerceV2/Pdp/PdpVariantRegistry.php || {
    printf '%s\n' 'ERROR: Chưa có nền Luxe Clarity PDP.' >&2
    exit 1
  }

grep -Fq "Route::prefix(\$prefix)" \
  routes/commerce_v2.php || {
    printf '%s\n' 'ERROR: Route Commerce V2 đã drift.' >&2
    exit 1
  }

grep -Fq "commerce-v2/commerce.css" \
  resources/views/commerce_v2/layouts/app.blade.php || {
    printf '%s\n' 'ERROR: Layout Commerce V2 đã drift.' >&2
    exit 1
  }

FILES=(
  'routes/commerce_v2.php'
  'resources/views/commerce_v2/layouts/app.blade.php'
  'resources/views/commerce_v2/pages/home.blade.php'
  'resources/views/commerce_v2/pages/shop.blade.php'
  'resources/views/commerce_v2/pages/search.blade.php'
  'resources/views/commerce_v2/pages/collection.blade.php'
  'resources/views/commerce_v2/pages/discover.blade.php'
  'resources/views/commerce_v2/pages/cart.blade.php'
  'resources/views/commerce_v2/pages/checkout.blade.php'
  'resources/views/commerce_v2/pages/checkout_confirm.blade.php'
  'resources/views/commerce_v2/pages/order_success.blade.php'
  'resources/views/commerce_v2/pages/account.blade.php'
  'resources/views/commerce_v2/pages/orders.blade.php'
  'resources/views/commerce_v2/pages/order.blade.php'
  'app/Services/CommerceV2/CommerceThemePreviewService.php'
  'app/Http/Controllers/CommerceV2/CommerceThemePreviewController.php'
  'app/Console/Commands/CommerceV2LuxeCommerceThemePreviewUrlCommand.php'
  'app/Console/Commands/CommerceV2LuxeCommerceThemeSmokeCommand.php'
  'resources/views/commerce_v2/themes/luxe_commerce_v1/shell/header.blade.php'
  'resources/views/commerce_v2/themes/luxe_commerce_v1/shell/footer.blade.php'
  'resources/views/commerce_v2/themes/luxe_commerce_v1/shell/bottom-nav.blade.php'
  'resources/views/commerce_v2/themes/luxe_commerce_v1/shell/preview-bar.blade.php'
  'resources/views/commerce_v2/themes/luxe_commerce_v1/partials/product-card.blade.php'
  'resources/views/commerce_v2/themes/luxe_commerce_v1/pages/home.blade.php'
  'resources/views/commerce_v2/themes/luxe_commerce_v1/pages/shop.blade.php'
  'resources/views/commerce_v2/themes/luxe_commerce_v1/pages/search.blade.php'
  'resources/views/commerce_v2/themes/luxe_commerce_v1/pages/collection.blade.php'
  'resources/views/commerce_v2/themes/luxe_commerce_v1/pages/discover.blade.php'
  'resources/views/commerce_v2/themes/luxe_commerce_v1/pages/cart.blade.php'
  'resources/views/commerce_v2/themes/luxe_commerce_v1/pages/checkout.blade.php'
  'resources/views/commerce_v2/themes/luxe_commerce_v1/pages/checkout-confirm.blade.php'
  'resources/views/commerce_v2/themes/luxe_commerce_v1/pages/order-success.blade.php'
  'resources/views/commerce_v2/themes/luxe_commerce_v1/pages/account.blade.php'
  'resources/views/commerce_v2/themes/luxe_commerce_v1/pages/orders.blade.php'
  'resources/views/commerce_v2/themes/luxe_commerce_v1/pages/order.blade.php'
  'public/commerce-v2/themes/luxe-commerce-v1.css'
  'public/commerce-v2/themes/luxe-commerce-v1.js'
)

mkdir -p "$BACKUP_DIR"
: > "$MANIFEST"

for FILE in "${FILES[@]}"
do
  if [ -e "$FILE" ]; then
    mkdir -p "$BACKUP_DIR/$(dirname "$FILE")"
    cp -p "$FILE" "$BACKUP_DIR/$FILE"
    printf 'existing\t%s\n' "$FILE" >> "$MANIFEST"
  else
    printf 'new\t%s\n' "$FILE" >> "$MANIFEST"
  fi
done

rollback_patch() {
  STATUS="$?"

  if [ "$PATCH_COMMITTED" -eq 1 ]; then
    exit "$STATUS"
  fi

  if [ -f "$MANIFEST" ]; then
    while IFS=$'\t' read -r KIND FILE
    do
      if [ "$KIND" = 'existing' ]; then
        mkdir -p "$(dirname "$FILE")"
        cp -p "$BACKUP_DIR/$FILE" "$FILE"
      elif [ "$KIND" = 'new' ]; then
        rm -f "$FILE"
      fi
    done < "$MANIFEST"
  fi

  printf 'PATCH_ROLLBACK=PASS status=%s\n' "$STATUS" >&2
  exit "$STATUS"
}

trap rollback_patch ERR INT TERM

python3 <<'PY'
from pathlib import Path
import base64
import json
import os

payload = json.loads(base64.b64decode('').decode('utf-8'))
page_map = json.loads('{"resources/views/commerce_v2/pages/home.blade.php": "commerce_v2.themes.luxe_commerce_v1.pages.home", "resources/views/commerce_v2/pages/shop.blade.php": "commerce_v2.themes.luxe_commerce_v1.pages.shop", "resources/views/commerce_v2/pages/search.blade.php": "commerce_v2.themes.luxe_commerce_v1.pages.search", "resources/views/commerce_v2/pages/collection.blade.php": "commerce_v2.themes.luxe_commerce_v1.pages.collection", "resources/views/commerce_v2/pages/discover.blade.php": "commerce_v2.themes.luxe_commerce_v1.pages.discover", "resources/views/commerce_v2/pages/cart.blade.php": "commerce_v2.themes.luxe_commerce_v1.pages.cart", "resources/views/commerce_v2/pages/checkout.blade.php": "commerce_v2.themes.luxe_commerce_v1.pages.checkout", "resources/views/commerce_v2/pages/checkout_confirm.blade.php": "commerce_v2.themes.luxe_commerce_v1.pages.checkout-confirm", "resources/views/commerce_v2/pages/order_success.blade.php": "commerce_v2.themes.luxe_commerce_v1.pages.order-success", "resources/views/commerce_v2/pages/account.blade.php": "commerce_v2.themes.luxe_commerce_v1.pages.account", "resources/views/commerce_v2/pages/orders.blade.php": "commerce_v2.themes.luxe_commerce_v1.pages.orders", "resources/views/commerce_v2/pages/order.blade.php": "commerce_v2.themes.luxe_commerce_v1.pages.order"}')

def atomic_write(path: Path, content: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.with_name(path.name + ".ai_patch_tmp")
    tmp.write_text(content, encoding="utf-8")
    os.replace(tmp, path)

for relative, content in payload.items():
    atomic_write(Path(relative), content)

route_path = Path("routes/commerce_v2.php")
route_text = route_path.read_text(encoding="utf-8")
route_marker = "AI_PATCH_LINXEN_LUXE_COMMERCE_THEME_V1_ROUTES"

if route_marker not in route_text:
    use_needle = (
        "use App\\Http\\Controllers\\CommerceV2\\"
        "PdpSizeAdviceController;\n"
    )
    use_replacement = (
        use_needle
        + "use App\\Http\\Controllers\\CommerceV2\\"
        "CommerceThemePreviewController;\n"
    )

    if use_needle not in route_text:
        raise SystemExit(
            "ROUTE_USE_INSERTION_POINT_MISSING"
        )

    route_text = route_text.replace(
        use_needle,
        use_replacement,
        1
    )
    group_needle = (
        "Route::prefix($prefix)\n"
        "    ->name('commerce.v2.')\n"
        "    ->group(function () {\n"
    )
    group_replacement = group_needle + """        /* AI_PATCH_LINXEN_LUXE_COMMERCE_THEME_V1_ROUTES_START */
        Route::get(
            '/preview/theme/luxe-commerce-v1/{target}',
            [
                CommerceThemePreviewController::class,
                'activate',
            ]
        )
            ->where(
                'target',
                'home|shop|search|discover|cart|checkout|account|orders'
            )
            ->middleware('signed')
            ->name('theme.preview');

        Route::get(
            '/preview/theme/exit',
            [
                CommerceThemePreviewController::class,
                'clear',
            ]
        )->name('theme.preview.exit');
        /* AI_PATCH_LINXEN_LUXE_COMMERCE_THEME_V1_ROUTES_END */

"""

    if group_needle not in route_text:
        raise SystemExit(
            "ROUTE_GROUP_INSERTION_POINT_MISSING"
        )

    route_text = route_text.replace(
        group_needle,
        group_replacement,
        1
    )
    atomic_write(route_path, route_text)

switch_marker = (
    "AI_PATCH_LINXEN_LUXE_COMMERCE_THEME_V1_PAGE_SWITCH"
)
condition = """@if(
    app(\\App\\Services\\CommerceV2\\CommerceThemePreviewService::class)
        ->active(session())
    === \\App\\Services\\CommerceV2\\CommerceThemePreviewService::THEME
)
"""

for relative, include_view in page_map.items():
    path = Path(relative)
    source = path.read_text(encoding="utf-8")

    if switch_marker in source:
        continue

    section_needle = "@section('content')"

    if section_needle not in source:
        raise SystemExit(
            "PAGE_CONTENT_SECTION_MISSING=" + relative
        )

    source = source.replace(
        section_needle,
        section_needle
        + "\n{{-- "
        + switch_marker
        + " --}}\n"
        + condition
        + "@include('"
        + include_view
        + "')\n"
        + "@else",
        1
    )
    end_index = source.rfind("@endsection")

    if end_index < 0:
        raise SystemExit(
            "PAGE_ENDSECTION_MISSING=" + relative
        )

    source = (
        source[:end_index]
        + "@endif\n"
        + source[end_index:]
    )
    atomic_write(path, source)

PY

