fi

printf '%s\n' 'LINXEN_LUXE_COMMERCE_UI_V1_1_SOURCE_PATCH=PASS'
printf '%s\n' 'THEME=luxe_commerce_v1'
printf '%s\n' 'PREVIEW_MODE=SIGNED_ACTIVATION_SESSION'
printf '%s\n' 'SESSION_MANAGER_CONTRACT=SUPPORTED'
printf '%s\n' 'LIVE_THEME=UNCHANGED'
printf '%s\n' 'PAGES=HOME_SHOP_SEARCH_COLLECTION_DISCOVER_CART_CHECKOUT_ORDER_SUCCESS_ACCOUNT_ORDERS'
printf '%s\n' 'PDP_LUXE_CLARITY=UNCHANGED'
printf '%s\n' 'EXACT_SELLABLE_SKU=PRESERVED'
printf '%s\n' 'CART_VALIDATION=PRESERVED'
printf '%s\n' 'CHECKOUT_QUOTE_IDEMPOTENCY=PRESERVED'
printf '%s\n' 'MIGRATION=NONE'
printf '%s\n' 'DB_MUTATION=NONE'
printf '%s\n' 'ORDER_PROVIDER_META_MUTATION=NONE'
printf 'BACKUP_DIR=%s\n' "$BACKUP_DIR"
